import copy, re, zipfile, shutil, os
from lxml import etree
from diff_match_patch import diff_match_patch

W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main"
XML = "http://www.w3.org/XML/1998/namespace"
def q(t): return "{%s}%s" % (W, t)

class Redliner:
    def __init__(self, src, author, date, initials="HWC"):
        self.src = src; self.author = author; self.date = date; self.initials = initials
        self.wd = "/workspace/work/build"
        shutil.rmtree(self.wd, ignore_errors=True)
        zipfile.ZipFile(src).extractall(self.wd)
        self.tree = etree.parse(self.wd + "/word/document.xml")
        self.body = self.tree.getroot().find(q("body"))
        self.paras = [p for p in self.body if p.tag == q("p")]
        self.rev = 1000
        self.comments = []  # (id, text)
        self.cid = 0
        self.tpl = {}

    def nid(self):
        self.rev += 1; return str(self.rev)

    def revattrs(self, el):
        el.set(q("id"), self.nid()); el.set(q("author"), self.author); el.set(q("date"), self.date)
        return el

    # --- formatting helpers
    def base_rpr(self, b=False, u=False, i=False):
        r = etree.Element(q("rPr"))
        f = etree.SubElement(r, q("rFonts")); f.set(q("ascii"), "Times New Roman"); f.set(q("hAnsi"), "Times New Roman")
        if b: etree.SubElement(r, q("b"))
        if i: etree.SubElement(r, q("i"))
        c = etree.SubElement(r, q("color")); c.set(q("val"), "000000")
        s = etree.SubElement(r, q("sz")); s.set(q("val"), "22")
        if u: x = etree.SubElement(r, q("u")); x.set(q("val"), "single")
        return r

    def mkrun(self, text, fmt, deleted=False):
        r = etree.Element(q("r"))
        r.append(self.base_rpr(*fmt))
        t = etree.SubElement(r, q("delText" if deleted else "t"))
        t.set("{%s}space" % XML, "preserve"); t.text = text
        return r

    @staticmethod
    def parse_markup(s):
        # ** = bold, __ = bold+underline, // = italic
        out = []
        b = u = it = False
        i = 0
        while i < len(s):
            if s.startswith("**", i): b = not b; i += 2; continue
            if s.startswith("__", i): u = not u; i += 2; continue
            if s.startswith("//", i): it = not it; i += 2; continue
            out.append((s[i], (b or u, u, it))); i += 1
        return out

    def orig_chars(self, p):
        out = []
        for r in p.findall(q("r")):
            rpr = r.find(q("rPr"))
            b = rpr is not None and rpr.find(q("b")) is not None
            u = rpr is not None and rpr.find(q("u")) is not None
            it = rpr is not None and rpr.find(q("i")) is not None
            for t in r.findall(q("t")):
                for ch in (t.text or ""):
                    out.append((ch, (b, u, it)))
        return out

    @staticmethod
    def groups(chars):
        res = []
        for ch, f in chars:
            if res and res[-1][1] == f: res[-1][0] += ch
            else: res.append([ch, f])
        return res

    def _strip_runs(self, p):
        for c in list(p):
            if c.tag != q("pPr"): p.remove(c)

    def word_diff(self, a, b):
        dmp = diff_match_patch()
        toks_a = re.findall(r"\w+|\s+|[^\w\s]", a); toks_b = re.findall(r"\w+|\s+|[^\w\s]", b)
        vocab = {}; 
        def enc(toks):
            s = []
            for t in toks:
                if t not in vocab: vocab[t] = chr(0xE000 + len(vocab)) if len(vocab) < 6000 else chr(0x10000 + len(vocab))
                s.append(vocab[t])
            return "".join(s)
        inv = None
        ea, eb = enc(toks_a), enc(toks_b)
        inv = {v: k for k, v in vocab.items()}
        diffs = dmp.diff_main(ea, eb, False)
        dmp.diff_cleanupSemantic(diffs)
        return [(op, "".join(inv[c] for c in txt)) for op, txt in diffs]

    # --- operations
    def modify(self, idx, markup, comment=None):
        p = self.paras[idx]
        old = self.orig_chars(p)
        new = self.parse_markup(markup)
        a = "".join(c for c, _ in old); b = "".join(c for c, _ in new)
        ops = self.word_diff(a, b)
        self._strip_runs(p)
        oi = ni = 0
        for op, txt in ops:
            L = len(txt)
            if op == 0:
                for t, f in self.groups(old[oi:oi+L]): p.append(self.mkrun(t, f))
                oi += L; ni += L
            elif op == -1:
                d = self.revattrs(etree.Element(q("del")))
                for t, f in self.groups(old[oi:oi+L]): d.append(self.mkrun(t, f, True))
                p.append(d); oi += L
            else:
                ins = self.revattrs(etree.Element(q("ins")))
                for t, f in self.groups(new[ni:ni+L]): ins.append(self.mkrun(t, f))
                p.append(ins); ni += L
        if comment: self.add_comment(p, comment)
        return p

    def delete(self, idx, comment=None):
        p = self.paras[idx]
        old = self.orig_chars(p)
        self._strip_runs(p)
        ppr = p.find(q("pPr"))
        if ppr is None: ppr = etree.SubElement(p, q("pPr")); p.insert(0, ppr)
        rpr = ppr.find(q("rPr"))
        if rpr is None: rpr = etree.SubElement(ppr, q("rPr"))
        rpr.append(self.revattrs(etree.Element(q("del"))))
        if old:
            d = self.revattrs(etree.Element(q("del")))
            for t, f in self.groups(old): d.append(self.mkrun(t, f, True))
            p.append(d)
        if comment: self.add_comment(p, comment)
        return p

    def new_para(self, markup, kind="body", comment=None):
        tpl = self.tpl[kind]
        p = etree.Element(q("p"))
        ppr = copy.deepcopy(tpl)
        for x in ppr.findall(q("rPr")): ppr.remove(x)
        rpr = etree.SubElement(ppr, q("rPr"))
        rpr.append(self.revattrs(etree.Element(q("ins"))))
        p.append(ppr)
        if markup:
            ins = self.revattrs(etree.Element(q("ins")))
            for t, f in self.groups(self.parse_markup(markup)): ins.append(self.mkrun(t, f))
            p.append(ins)
        if comment: self.add_comment(p, comment)
        return p

    def insert_after(self, anchor, items):
        # anchor: original index or element; items: list of (markup, kind, comment)
        el = self.paras[anchor] if isinstance(anchor, int) else anchor
        for it in items:
            markup, kind = it[0], it[1]; comment = it[2] if len(it) > 2 else None
            np_ = self.new_para(markup, kind, comment)
            el.addnext(np_); el = np_
        return el

    def comment(self, idx, text):
        self.add_comment(self.paras[idx], text)

    def add_comment(self, p, text):
        cid = str(self.cid); self.cid += 1
        self.comments.append((cid, text))
        s = etree.Element(q("commentRangeStart")); s.set(q("id"), cid)
        e = etree.Element(q("commentRangeEnd")); e.set(q("id"), cid)
        ppr = p.find(q("pPr"))
        if ppr is not None: ppr.addnext(s)
        else: p.insert(0, s)
        p.append(e)
        r = etree.SubElement(p, q("r"))
        rp = etree.SubElement(r, q("rPr")); rs = etree.SubElement(rp, q("rStyle")); rs.set(q("val"), "CommentReference")
        cr = etree.SubElement(r, q("commentReference")); cr.set(q("id"), cid)

    def save(self, out):
        self.tree.write(self.wd + "/word/document.xml", xml_declaration=True, encoding="UTF-8", standalone=True)
        # comments part
        root = etree.Element(q("comments"), nsmap={"w": W})
        for cid, text in self.comments:
            c = etree.SubElement(root, q("comment")); c.set(q("id"), cid); c.set(q("author"), self.author)
            c.set(q("date"), self.date); c.set(q("initials"), self.initials)
            for line in text.split("\n"):
                pp = etree.SubElement(c, q("p")); r = etree.SubElement(pp, q("r"))
                rpr = etree.SubElement(r, q("rPr")); sz = etree.SubElement(rpr, q("sz")); sz.set(q("val"), "18")
                t = etree.SubElement(r, q("t")); t.set("{%s}space" % XML, "preserve"); t.text = line
        etree.ElementTree(root).write(self.wd + "/word/comments.xml", xml_declaration=True, encoding="UTF-8", standalone=True)
        ct = self.wd + "/[Content_Types].xml"; s = open(ct).read()
        if "/word/comments.xml" not in s:
            s = s.replace("</Types>", "<Override PartName=\"/word/comments.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.wordprocessingml.comments+xml\"/></Types>")
            open(ct, "w").write(s)
        rel = self.wd + "/word/_rels/document.xml.rels"; s = open(rel).read()
        if "relationships/comments" not in s:
            s = s.replace("</Relationships>", "<Relationship Id=\"rId99\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/comments\" Target=\"comments.xml\"/></Relationships>")
            open(rel, "w").write(s)
        st = self.wd + "/word/settings.xml"; s = open(st).read()
        if "trackRevisions" not in s:
            s = re.sub(r"(<w:proofState[^>]*/>)", r"\1<w:trackRevisions/>", s, count=1)
            open(st, "w").write(s)
        if os.path.exists(out): os.remove(out)
        with zipfile.ZipFile(out, "w", zipfile.ZIP_DEFLATED) as z:
            # content types first
            z.write(ct, "[Content_Types].xml")
            for dp, dn, fn in os.walk(self.wd):
                for f in fn:
                    full = os.path.join(dp, f); arc = os.path.relpath(full, self.wd)
                    if arc == "[Content_Types].xml": continue
                    z.write(full, arc)
